import React from 'react';
import './Process.css';

const STEPS = [
  {
    num: '01',
    title: 'Discovery & Alignment',
    desc: 'Aligning on goals, user needs, and technical constraints to define a clear roadmap.',
  },
  {
    num: '02',
    title: 'Planning & Strategy',
    desc: 'Technical architecture, resource allocation, and risk assessment for project success.',
  },
  {
    num: '03',
    title: 'Design & Prototyping',
    desc: 'User flows and interactive prototypes that validate assumptions before building.',
  },
  {
    num: '04',
    title: 'Development & QA',
    desc: 'Iterative building with continuous testing and transparent progress updates.',
  },
  {
    num: '05',
    title: 'Launch & Support',
    desc: 'Deployment, monitoring, and performance optimization as your product evolves.',
  },
];

export default function Process() {
  return (
    <section className="process-section py-24 border-t border-black bg-white" id="process">
      <div className="container">
        <div className="process__header mb-16">
          <div className="hero__identity-wrapper">
            <div className="hero__identity-line" />
            <span className="hero__pre-name font-mono">The Workflow</span>
          </div>
          <h2 className="font-display text-4xl lg:text-6xl font-bold tracking-tight">My Development Process</h2>
          <p className="text-xl mt-6 text-gray-600 max-w-[60ch] leading-relaxed">
            A structured, product-first approach designed to reduce risk, ensure clarity, and deliver predictable outcomes.
          </p>
        </div>

        <div className="process__grid grid grid-cols-1 md:grid-cols-2 lg:grid-cols-5 border-l border-t border-black">
          {STEPS.map((step) => (
            <div key={step.num} className="process__step p-8 border-r border-b border-black hover:bg-gray-50 transition-colors group">
              <span className="process__num font-mono text-xs font-bold text-blue-600 mb-8 block tracking-widest uppercase">
                Step {step.num}
              </span>
              <h3 className="font-display text-xl font-bold mb-4 leading-tight group-hover:text-blue-600 transition-colors">
                {step.title}
              </h3>
              <p className="text-sm font-mono text-gray-500 leading-relaxed">
                {step.desc}
              </p>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
}
